two-sum-fn.java:
import java.util.*;
class Solution {
    int[] solve(int[] nums, int target) {
        HashMap<Integer,Integer> pos = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (pos.containsKey(target - nums[i])) return new int[]{pos.get(target - nums[i]) + 1, i + 1};
            pos.put(nums[i], i);
        }
        return new int[]{-1};
    }
}

