class Solution {
    String solve(String s, int k) {
        k %= 26; StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c >= 'a' && c <= 'z') sb.append((char)((c - 'a' + k) % 26 + 'a'));
            else sb.append(c);
        }
        return sb.toString();
    }
}

