                dp[i] = True
                break
    return dp[n]

word-break.java:
import java.util.*;
class Solution {
    boolean solve(String s, String[] words) {
        Set<String> w = new HashSet<>(Arrays.asList(words));
        int n = s.length(); boolean[] dp = new boolean[n + 1]; dp[0] = true;
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                if (dp[j] && w.contains(s.substring(j, i))) { dp[i] = true; break; }
        return dp[n];
    }
}

count-primes.python:
def solve(n):
    if n < 3: return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    i = 2
    while i * i < n:
        if sieve[i]:
            for j in range(i * i, n, i): sieve[j] = False
        i += 1
    return sum(sieve)

