    int n;
    int solve(int n){ this.n=n; return go(0,0,0,0); }
    int go(int r,int cols,int d1,int d2){ int full=(1<<n)-1; if(cols==full) return 1; int avail=full & ~(cols|d1|d2); int t=0; while(avail!=0){ int p=avail&(-avail); avail-=p; t+=go(r+1, cols|p, (d1|p)<<1, (d2|p)>>1); } return t; }
}

