def solve(n):
    full=(1<<n)-1
    def go(cols,d1,d2):
        if cols==full: return 1
        avail=full & ~(cols|d1|d2); t=0
        while avail:
            p=avail&(-avail); avail-=p; t+=go(cols|p,(d1|p)<<1,(d2|p)>>1)
        return t
    return go(0,0,0)

