class Solution {
    char[][] g; int R,C; String w;
    boolean solve(String[] grid, String word){ R=grid.length; C=R>0?grid[0].length():0; g=new char[R][]; for(int i=0;i<R;i++) g[i]=grid[i].toCharArray(); w=word; boolean[][] s=new boolean[R][C]; for(int r=0;r<R;r++) for(int c=0;c<C;c++) if(dfs(r,c,0,s)) return true; return false; }
    boolean dfs(int r,int c,int i,boolean[][] s){ if(i==w.length()) return true; if(r<0||r>=R||c<0||c>=C||s[r][c]||g[r][c]!=w.charAt(i)) return false; s[r][c]=true; boolean ok=dfs(r+1,c,i+1,s)||dfs(r-1,c,i+1,s)||dfs(r,c+1,i+1,s)||dfs(r,c-1,i+1,s); s[r][c]=false; return ok; }
}

