import heapq
from collections import Counter
def solve(s):
    c=Counter(s); n=len(s)
    if max(c.values())>(n+1)//2: return ''
    h=[(-v,ch) for ch,v in c.items()]; heapq.heapify(h)
    res=[]; prev=None
    while h:
        v,ch=heapq.heappop(h); res.append(ch)
        if prev and prev[0]<0: heapq.heappush(h,prev)
        prev=(v+1,ch)
    return ''.join(res)

