public class Main {
    public static void main(String[] a) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int q=Integer.parseInt(br.readLine().trim()); int cap=0;
        LinkedHashMap<Integer,Integer> od=new LinkedHashMap<>(); StringBuilder sb=new StringBuilder();
        for(int i=0;i<q;i++){ StringTokenizer t=new StringTokenizer(br.readLine()); String op=t.nextToken();
            if(op.equals("cap")) cap=Integer.parseInt(t.nextToken());
            else if(op.equals("put")){ int k=Integer.parseInt(t.nextToken()), v=Integer.parseInt(t.nextToken()); if(od.containsKey(k)) od.remove(k); od.put(k,v); if(od.size()>cap){ int oldest=od.keySet().iterator().next(); od.remove(oldest); } }
            else if(op.equals("get")){ int k=Integer.parseInt(t.nextToken()); if(od.containsKey(k)){ int v=od.remove(k); od.put(k,v); sb.append(v).append('\n'); } else sb.append(-1).append('\n'); } }
        System.out.print(sb);
    }
}

