import heapq
def solve(n, u, v, w, src):
    adj=[[] for _ in range(n)]
    for a,b,wt in zip(u,v,w): adj[a].append((b,wt))
    INF=float('inf'); dist=[INF]*n; dist[src]=0; pq=[(0,src)]
    while pq:
        d,x=heapq.heappop(pq)
        if d>dist[x]: continue
        for y,wt in adj[x]:
            if d+wt<dist[y]: dist[y]=d+wt; heapq.heappush(pq,(dist[y],y))
    m=max(dist)
    return m if m<INF else -1

