import java.util.*;
class Solution {
    int[] p;
    int find(int x){ while(p[x]!=x){ p[x]=p[p[x]]; x=p[x]; } return x; }
    int solve(int n, int[] u, int[] v, int[] w){ Integer[] idx=new Integer[u.length]; for(int i=0;i<idx.length;i++) idx[i]=i; Arrays.sort(idx,(a,b)->w[a]-w[b]); p=new int[n]; for(int i=0;i<n;i++) p[i]=i; int total=0, used=0; for(int i:idx){ int a=find(u[i]), b=find(v[i]); if(a!=b){ p[a]=b; total+=w[i]; used++; } } return used==n-1?total:-1; }
}

