def solve(n, u, v, w):
    p=list(range(n))
    def f(x):
        while p[x]!=x: p[x]=p[p[x]]; x=p[x]
        return x
    total=0; used=0
    for wt,a,b in sorted(zip(w,u,v)):
        ra,rb=f(a),f(b)
        if ra!=rb: p[ra]=rb; total+=wt; used+=1
    return total if used==n-1 else -1

