import java.util.*;
class Solution {
    boolean solve(int n, int[] u, int[] v){ List<Integer>[] adj=new List[n]; for(int i=0;i<n;i++) adj[i]=new ArrayList<>(); for(int i=0;i<u.length;i++){ adj[u[i]].add(v[i]); adj[v[i]].add(u[i]); } int[] col=new int[n]; Arrays.fill(col,-1); for(int s=0;s<n;s++){ if(col[s]==-1){ col[s]=0; ArrayDeque<Integer> q=new ArrayDeque<>(); q.add(s); while(!q.isEmpty()){ int x=q.poll(); for(int y:adj[x]){ if(col[y]==-1){ col[y]=col[x]^1; q.add(y); } else if(col[y]==col[x]) return false; } } } } return true; }
}

