from collections import deque
def solve(n, u, v):
    adj=[[] for _ in range(n)]
    for a,b in zip(u,v): adj[a].append(b); adj[b].append(a)
    col=[-1]*n
    for s in range(n):
        if col[s]==-1:
            col[s]=0; q=deque([s])
            while q:
                x=q.popleft()
                for y in adj[x]:
                    if col[y]==-1: col[y]=col[x]^1; q.append(y)
                    elif col[y]==col[x]: return False
    return True

