import java.util.*;
import java.io.*;
public class Main {
    static class Node { Node[] ch=new Node[26]; boolean end; }
    static Node root=new Node();
    static void insert(String w){ Node n=root; for(char c:w.toCharArray()){ int i=c-'a'; if(n.ch[i]==null) n.ch[i]=new Node(); n=n.ch[i]; } n.end=true; }
    static Node walk(String w){ Node n=root; for(char c:w.toCharArray()){ int i=c-'a'; if(n.ch[i]==null) return null; n=n.ch[i]; } return n; }
    public static void main(String[] a) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int q=Integer.parseInt(br.readLine().trim()); StringBuilder sb=new StringBuilder();
        for(int i=0;i<q;i++){ StringTokenizer t=new StringTokenizer(br.readLine()); String op=t.nextToken(), w=t.nextToken();
            if(op.equals("insert")) insert(w);
            else if(op.equals("search")){ Node n=walk(w); sb.append(n!=null&&n.end?"true":"false").append('\n'); }
            else { Node n=walk(w); sb.append(n!=null?"true":"false").append('\n'); } }
        System.out.print(sb);
    }
}

