import sys
def main():
    L=sys.stdin.read().split('\n'); q=int(L[0]); words=set(); out=[]
    for i in range(1,q+1):
        p=L[i].split(); op=p[0]
        if op=='insert': words.add(p[1])
        elif op=='search': out.append('true' if p[1] in words else 'false')
        else: out.append('true' if any(w.startswith(p[1]) for w in words) else 'false')
    sys.stdout.write('\n'.join(out))
main()

