import java.util.*;
class Solution {
    int[] solve(String[] words, String[] queries){ Set<String> s=new HashSet<>(Arrays.asList(words)); int[] r=new int[queries.length]; for(int i=0;i<queries.length;i++) r[i]=s.contains(queries[i])?1:0; return r; }
}

